/// The quiz in [lang] (English for anything else).
List<Trivia> i18nTriviaOf(String lang) {
  switch (lang) {
    case "nl":
      return _triviaNl;
    case "fr":
      return _triviaFr;
    case "de":
      return _triviaDe;
    case "es":
      return _triviaEs;
    default:
      return _triviaEn;
  }
}

/// The word scramble in [lang] (English for anything else).
List<Word> i18nWordsOf(String lang) {
  switch (lang) {
    case "nl":
      return _wordsNl;
    case "fr":
      return _wordsFr;
    case "de":
      return _wordsDe;
    case "es":
      return _wordsEs;
    default:
      return _wordsEn;
  }
}

